-- ═══════════════════════════════════════════════════════════════════════
-- GALERÍA DE EJERCICIOS · 2226 fichas de la librería de Trainerize
-- ═══════════════════════════════════════════════════════════════════════
--
-- Qué hace: mete en tu tabla `ejercicios` la librería completa de sistema de
-- Trainerize, ya traducida a TU modelo de datos (tipo, segmento, patrón,
-- nivel, equipo, lugar, músculos y unilateral).
--
-- ── TRES DECISIONES QUE VIENEN APLICADAS ──────────────────────────────
--
-- 1. SIN VÍDEO. Los 2191 vídeos del volcado eran loops privados de
--    Vimeo, de dominio restringido: no se pueden embeber desde tu app, así
--    que `video_url` y `video_ref` se descartan y todos entran con
--    `video_fuente = 'ninguno'`. El camino de YouTube del formulario queda
--    intacto: los vídeos se ponen a mano desde la galería, ficha a ficha.
--    (En el volcado no había ni un solo YouTube que conservar.)
--
-- 2. DESCRIPCIÓN Y CLAVES EN ESPAÑOL, ESCRITAS DE CERO. No son traducción
--    del texto de Trainerize. Las claves técnicas ni siquiera existen allí
--    (su campo equivalente está vacío en las 2226 filas), así que
--    escribirlas es columna nueva, no copia.
--
-- 3. NO DUPLICA LO QUE YA TIENES. Las 160 fichas que creó la carga de
--    rutinas están TODAS en este volcado. Si esto se insertara a pelo,
--    tendrías 160 pares repetidos y las rutinas apuntando a la copia
--    equivocada. Por eso el archivo FUSIONA: a lo que ya existe le añade los
--    datos que le faltaban (músculos, nivel, unilateral, etiquetas) y le
--    respeta su nombre en español; solo inserta lo que no tenías.
--
-- PASO 1: cambia el UUID de abajo por tu user_id de coach.
--         Lo sacas con:  select user_id from clientes limit 1;
-- PASO 2: ejecuta el archivo entero en el SQL Editor del Supabase del CRM.
--
-- Se puede correr dos veces: la segunda no duplica nada, solo reescribe.
-- ═══════════════════════════════════════════════════════════════════════

begin;

create temp table _coach (id uuid) on commit drop;

-- Normaliza para comparar nombres: minúsculas, sin tildes, sin puntuación.
-- Es la misma regla que usa el CRM, para que el cruce no falle por un acento.
create or replace function ecm_norm(t text) returns text language sql immutable as $fn$
  select btrim(regexp_replace(
           lower(translate(coalesce(t,''),
                 'áàäâãéèëêíìïîóòöôõúùüûñçÁÀÄÂÃÉÈËÊÍÌÏÎÓÒÖÔÕÚÙÜÛÑÇ',
                 'aaaaaeeeeiiiiooooouuuuncAAAAAEEEEIIIIOOOOOUUUUNC')),
           '[^a-z0-9]+', ' ', 'g'));
$fn$;

-- Todo el volcado entra primero aquí; después se fusiona en dos pasos.
create temp table _ej_in (
  nombre text, alias text, descripcion text, claves text[], tipo text,
  segmento text, patron text, nivel text, equipo text[], lugar text[],
  musculos text[], unilateral boolean, tags text[]
) on commit drop;



-- ── 1 · ACTUALIZAR lo que ya existe ─────────────────────────────────────
-- Cruza por nombre O por alias, en los dos sentidos: tus fichas guardan el
-- nombre en español con el de Trainerize en `alias`, y el volcado al revés.
-- Se respeta TU nombre y TU alias; solo se rellena la clasificación.
with pares as (
  select e.id as ej_id, i.*
    from ejercicios e
    join _ej_in i
      on ecm_norm(e.nombre) = ecm_norm(i.nombre)
      or ecm_norm(e.alias)  = ecm_norm(i.nombre)
      or ecm_norm(e.nombre) = ecm_norm(i.alias)
   where e.user_id = (select id from _coach)
)
update ejercicios e set
  tipo       = coalesce(p.tipo, e.tipo),
  segmento   = coalesce(p.segmento, e.segmento),
  patron     = coalesce(p.patron, e.patron),
  nivel      = coalesce(p.nivel, e.nivel),
  equipo     = case when cardinality(p.equipo)   > 0 then p.equipo   else e.equipo end,
  lugar      = case when cardinality(p.lugar)    > 0 then p.lugar    else e.lugar end,
  musculos_primarios = case when cardinality(p.musculos) > 0 then p.musculos else e.musculos_primarios end,
  unilateral = p.unilateral,
  -- las etiquetas se SUMAN: no se pierde 'importado-trainerize' de la carga
  tags = (select array(select distinct unnest(coalesce(e.tags,'{}') || coalesce(p.tags,'{}')))),
  -- descripción y claves solo si vienen escritas en español y la ficha no tenía
  descripcion     = coalesce(nullif(p.descripcion,''), e.descripcion),
  claves_tecnicas = case when cardinality(p.claves) > 0 then p.claves else e.claves_tecnicas end,
  updated_at = now()
from pares p
where e.id = p.ej_id;

-- ── 2 · INSERTAR lo que falta ───────────────────────────────────────────
                        tipo, segmento, patron, nivel, equipo, lugar,
                        musculos_primarios, musculos_secundarios, unilateral,
                        tags, video_fuente, archivado)
select (select id from _coach), i.nombre, i.alias, nullif(i.descripcion,''), i.claves,
       i.tipo, i.segmento, i.patron, i.nivel, i.equipo, i.lugar,
       i.musculos, '{}', i.unilateral, i.tags, 'ninguno', false
  from _ej_in i
 where not exists (
   select 1 from ejercicios e
    where e.user_id = (select id from _coach)
      and (ecm_norm(e.nombre) = ecm_norm(i.nombre)
        or ecm_norm(e.alias)  = ecm_norm(i.nombre)
        or ecm_norm(e.nombre) = ecm_norm(i.alias))
 );

do $$
declare v_tot int; v_desc int;
begin
  select count(*) into v_tot  from ejercicios where user_id = (select id from _coach);
  select count(*) into v_desc from ejercicios where user_id = (select id from _coach)
     and descripcion is not null and descripcion <> '';
  raise notice 'Galería: % ejercicios · % con descripción en español.', v_tot, v_desc;
end $$;

commit;

drop function if exists ecm_norm(text);

